//
//  SocksLogProxy.swift
//  Latchkey
//
//  A tiny SOCKS5 pass-through relay that sits between WebKit and tsnet's real
//  SOCKS5 proxy, logging **every** connection attempt and its outcome.
//
//  ## Why this exists
//
//  When chasing the "invalid URL" (-1000) failures, the single most valuable
//  fact is: *for a given URL, did the request reach the proxy at all, and if so
//  what did tsnet say?* That distinguishes the two candidate mechanisms:
//
//   * **iOS never sent it to us** \u2014 the OS matched `matchDomains`, decided the
//     host wasn't ours, and resolved/dialed it itself. Nothing appears here.
//   * **It reached us and tsnet couldn't dial it** \u2014 a CONNECT appears here with
//     a non-zero SOCKS reply code. (Measured: WebKit reports -1000 for *every*
//     SOCKS failure reply, so the error code alone can't tell you which.)
//
//  tsnet's own SOCKS server (`net/socks5`) only logs *failures*, and not the
//  reply code, so absence of its log lines proves nothing. This relay logs both
//  directions explicitly.
//
//  It is also the only diagnostic channel on a device that can't be attached to
//  a Mac (no `log stream`, no Console.app) \u2014 pair it with Settings \u2192 Logs.
//
//  ## How it works
//
//  Listens on 127.0.0.1 (an OS-assigned port) and relays bytes verbatim to
//  tsnet's loopback SOCKS5 address. It does not modify the stream: it *parses a
//  copy* of the first few messages in each direction to recover the requested
//  host/port and the reply code, then gets out of the way and pumps bytes.
//  Credentials pass through untouched, so tsnet's auth is unaffected.
//
//  Enabled by default (the logging is cheap and the diagnostic value is high);
//  set `APERTURE_NO_SOCKS_LOG=1` / `-NoSocksLog` to bypass it and point WebKit
//  straight at tsnet.
//
//  ## Housekeeping (R30)
//
//  Being in the data path by default, the relay is bounded: `SocksRelayCapacity`
//  caps concurrent sessions and picks who goes at the cap. And its own
//  listener can be defuncted by iOS while tsnet's stays up (see
//  `restartListener`); `TSNetManager` asks this object whether it accepted
//  anything for a failed load, probes the port with a loopback connect
//  (`probe`), and restarts the listener when the probe fails. Both decisions
//  are in `App/Network/SocksRelayPolicy.swift`. Everything mutable here is
//  confined to `queue`; a listener that reports failure after it was ready
//  is handed to `onListenerFailed`, so the manager can replace it.
//

import Foundation
import Network

/// Relays SOCKS5 traffic to tsnet's proxy, logging each attempt + outcome.
///
/// `@unchecked Sendable`: state is confined to `queue`, a serial dispatch queue
/// (Network.framework hands callbacks there), not to an actor \u2014 `NWListener`'s
/// callback API isn't async, and the relay must be usable from the nonisolated
/// contexts that start the node.
nonisolated final class SocksLogProxy: @unchecked Sendable {

    /// Whether the relay should be used at all. On by default; the logging is a
    /// few lines per navigation. Disable with `-NoSocksLog` /
    /// `APERTURE_NO_SOCKS_LOG=1` to point WebKit directly at tsnet (useful to
    /// rule the relay itself out of any investigation).
    nonisolated static func isEnabled() -> Bool {
        // The off switch is a test hook (R15); R10's anti-leak variant needs
        // it, because with the relay on WebKit always talks to an in-app
        // listener, which masks the proxy-unreachable path.
        if TestHooks.environment("APERTURE_NO_SOCKS_LOG") == "1" { return false }
        return !TestHooks.flag("-NoSocksLog")
    }

    /// tsnet's loopback SOCKS5 listener. Read by the manager if a restart
    /// cannot start a listener and WebKit has to be pointed at tsnet directly.
    let upstreamHost: String
    let upstreamPort: UInt16
    private let capacity: SocksRelayCapacity
    /// Called, on the relay's queue, when a listener that had reached
    /// `.ready` reports `.failed` (R30 review): iOS reporting a defuncted
    /// listener rather than leaving it looking alive. The manager replaces
    /// it, within its restart budget. The listener is already gone by then.
    private let onListenerFailed: (@Sendable (SocksLogProxy) -> Void)?
    private let queue = DispatchQueue(label: "net.lixom.latchkey.sockslog")
    /// Confined to `queue`, as is every other mutable thing here: `start`,
    /// `stop`, `restartListener` and the state handlers all touch it there.
    private var listener: NWListener?
    /// Listeners that reached `.ready` so far. The log carries it, and the
    /// host tests tell a restarted listener from the old one by it: an
    /// ephemeral port can be handed out twice.
    private var listenerGeneration: UInt64 = 0
    /// Monotonic id so a CONNECT and its reply can be correlated in the log.
    /// Process-wide, not per relay: a replaced relay goes on logging its
    /// sessions next to its successor's (M6 review), and two `socks[1]`s in
    /// one log would be ambiguous.
    nonisolated(unsafe) private static var nextID: UInt64 = 1
    private static let nextIDLock = NSLock()
    private static func takeID() -> UInt64 {
        nextIDLock.lock()
        defer { nextIDLock.unlock() }
        let id = nextID
        nextID &+= 1
        return id
    }
    private var activeClients: [UInt64: NWConnection] = [:]
    private var activeUpstreams: [UInt64: NWConnection] = [:]
    /// Parse state and last activity per admitted session (R30).
    private var sessions: [UInt64: Session] = [:]
    private var lifecycleEvents: UInt64 = 0
    /// When the listener last accepted a client: the evidence a failed page
    /// load is judged against (R30).
    private var lastAcceptedAt: Date?
    private var refusals: UInt64 = 0
    private var evictions: UInt64 = 0

    /// Called with every CONNECT the tailnet proxy refused (F4 §4.5). A
    /// callback, not a reference to `TSNetModel`, for the same reason
    /// `onListenerFailed` is one: this relay runs on its own queue and is
    /// deliberately usable without the app around it (its 99 host checks
    /// construct it directly). F4 §4.5 said to publish on the model from here;
    /// the owner does that, one hop away.
    private let onProxyReply: (@Sendable (ProxyReply) -> Void)?

    init(upstreamHost: String, upstreamPort: UInt16,
         capacity: SocksRelayCapacity = SocksRelayCapacity(),
         onListenerFailed: (@Sendable (SocksLogProxy) -> Void)? = nil,
         onProxyReply: (@Sendable (ProxyReply) -> Void)? = nil) {
        self.upstreamHost = upstreamHost
        self.upstreamPort = upstreamPort
        self.capacity = capacity
        self.onListenerFailed = onListenerFailed
        self.onProxyReply = onProxyReply
    }

    /// How long a listener may take to reach `.ready` before it is given up
    /// on. Loopback takes microseconds; this is the pathological bound.
    nonisolated static let startTimeout: TimeInterval = 3

    /// Starts listening and returns the local port WebKit should point at, or
    /// nil if the listener couldn't start (caller then uses tsnet directly).
    /// Waits for the port (see `startListener`): the proxy configuration is
    /// built synchronously from it when the node comes up.
    func start() -> UInt16? {
        let result = Box<UInt16?>(nil)
        let done = DispatchSemaphore(value: 0)
        queue.async { [self] in
            startListener { port in
                result.value = port
                done.signal()
            }
        }
        _ = done.wait(timeout: .now() + Self.startTimeout + 1)
        return result.value
    }

    /// Creates a listener on `queue` and hands `completion` (also on `queue`)
    /// its port once it is `.ready`, or nil if it failed, was cancelled, or
    /// took longer than `startTimeout`. Exactly one completion.
    ///
    /// The OS assigns the port asynchronously: `listener.port` is 0 (or nil)
    /// until the listener actually reaches `.ready`, so that state is waited
    /// for rather than `.port` polled — otherwise WebKit gets pointed at
    /// port 0 and every load fails.
    private func startListener(completion: @escaping @Sendable (UInt16?) -> Void) {
        dispatchPrecondition(condition: .onQueue(queue))
        let l: NWListener
        do {
            let params = NWParameters.tcp
            params.requiredInterfaceType = .loopback
            l = try NWListener(using: params)
        } catch {
            logger.log("sockslog: failed to start (\(error)); using tsnet proxy directly")
            completion(nil)
            return
        }
        l.newConnectionHandler = { [weak self] conn in
            self?.handle(client: conn)
        }

        let progress = StartProgress()
        l.stateUpdateHandler = { [weak self] state in
            guard let self else { return }
            switch state {
            case .ready:
                guard !progress.settled else { return }
                progress.settled = true
                guard let port = l.port?.rawValue, port != 0 else {
                    logger.log("sockslog: listener ready without a port; using tsnet proxy directly")
                    l.cancel()
                    completion(nil)
                    return
                }
                progress.ready = true
                self.listener = l
                self.listenerGeneration &+= 1
                logger.log("sockslog: relay listening on 127.0.0.1:\(port) -> tsnet \(self.upstreamHost):\(self.upstreamPort) (listener \(self.listenerGeneration))")
                completion(port)
            case .failed(let error):
                if progress.ready {
                    // After `.ready`: iOS reporting the defuncted listener.
                    // It is dead; say so to the manager (R30 review).
                    logger.log("sockslog: listener failed after ready: \(error); asking for a replacement")
                    if self.listener === l { self.listener = nil }
                    self.onListenerFailed?(self)
                } else if !progress.settled {
                    progress.settled = true
                    logger.log("sockslog: listener failed: \(error); using tsnet proxy directly")
                    completion(nil)
                }
            case .cancelled:
                // Our own doing (stop, restart, the test hook), unless it
                // happened before ready, when it ends the start.
                if !progress.settled {
                    progress.settled = true
                    completion(nil)
                }
            case .waiting(let error):
                logger.log("sockslog: listener waiting: \(error)")
            default:
                break
            }
        }
        l.start(queue: queue)
        queue.asyncAfter(deadline: .now() + Self.startTimeout) {
            guard !progress.settled else { return }
            progress.settled = true
            logger.log("sockslog: listener not ready after \(Int(Self.startTimeout))s (state=\(l.state)); using tsnet proxy directly")
            l.cancel()
            completion(nil)
        }
    }

    /// Closes the listener. The sessions it accepted are not cut: they run on
    /// to their end, and keep this object alive until then (see `pump`).
    /// Holds the relay strongly too (M6 review): the manager drops its
    /// reference right after calling this, and with no session left a weak
    /// capture found nil, never cancelled the listener, and left a port that
    /// accepted connections nobody served.
    func stop() {
        queue.async { [self] in
            listener?.cancel()
            listener = nil
        }
    }

    /// Replaces only the app-owned listening socket after iOS suspension.
    /// Existing relay sessions keep using this object and are not disturbed.
    /// Apple may defunct a loopback listener while leaving its NWListener object
    /// apparently alive; a fresh OS-assigned port is therefore required.
    /// Called by `TSNetManager.restartSocksRelay` on `SocksRelayRecovery`'s
    /// verdict (R30); the caller republishes the proxy configuration.
    /// Asynchronous: nothing waits on the main actor for the new port (R30
    /// review). `completion` runs on the relay's queue.
    func restartListener(completion: @escaping @Sendable (UInt16?) -> Void) {
        queue.async { [self] in
            listener?.cancel()
            listener = nil
            startListener(completion: completion)
        }
    }

    /// `restartListener(completion:)`, awaited.
    func restartListener() async -> UInt16? {
        await withCheckedContinuation { continuation in
            restartListener { continuation.resume(returning: $0) }
        }
    }

    /// Whether the listener accepted a client at or after `since`: for a page
    /// load that failed, whether the load reached the relay at all (R30).
    func hasAcceptedSession(since: Date) -> Bool {
        queue.sync { lastAcceptedAt.map { $0 >= since } ?? false }
    }

    /// Sessions being relayed right now.
    var activeSessionCount: Int {
        queue.sync { sessions.count }
    }

    /// How many listeners have reached `.ready` in this relay's life.
    var listenerStarts: UInt64 {
        queue.sync { listenerGeneration }
    }

    // MARK: - The self-probe (R30 review)

    /// How long a probe waits for the connect to be accepted or refused. A
    /// live loopback listener answers in microseconds; a defuncted socket
    /// refuses at once or, at worst, drops the SYN.
    nonisolated static let probeTimeout: TimeInterval = 2
    nonisolated private static let probeQueue = DispatchQueue(label: "net.lixom.latchkey.sockslog.probe")

    /// Whether anything accepts a TCP connection on 127.0.0.1:`port`: the
    /// relay's own listener, asked directly. A connect that completes is
    /// accepted by the relay like any client (one accept/finish pair in the
    /// log; no bytes are sent) and closed at once. Never blocks the caller:
    /// the connect runs on its own queue, `completion` too.
    nonisolated static func probe(port: UInt16, timeout: TimeInterval = probeTimeout,
                                  completion: @escaping @Sendable (SocksRelayRecovery.ListenerProbe) -> Void) {
        let params = NWParameters.tcp
        params.requiredInterfaceType = .loopback
        let connection = NWConnection(host: "127.0.0.1",
                                      port: NWEndpoint.Port(rawValue: port) ?? .any,
                                      using: params)
        let progress = StartProgress()
        let finish: @Sendable (SocksRelayRecovery.ListenerProbe) -> Void = { outcome in
            guard !progress.settled else { return }
            progress.settled = true
            connection.cancel()
            completion(outcome)
        }
        connection.stateUpdateHandler = { state in
            switch state {
            case .ready:
                finish(.answers)
            case .waiting(let error):
                // A refused loopback connect parks the connection here, "for
                // a better path", rather than failing it.
                logger.log("sockslog: probe of 127.0.0.1:\(port) refused: \(error)")
                finish(.refused)
            case .failed(let error):
                logger.log("sockslog: probe of 127.0.0.1:\(port) failed: \(error)")
                finish(.refused)
            default:
                break
            }
        }
        connection.start(queue: probeQueue)
        probeQueue.asyncAfter(deadline: .now() + timeout) {
            finish(.timedOut)
        }
    }

    /// `probe(port:timeout:completion:)`, awaited.
    nonisolated static func probe(port: UInt16, timeout: TimeInterval = probeTimeout) async
        -> SocksRelayRecovery.ListenerProbe {
        await withCheckedContinuation { continuation in
            probe(port: port, timeout: timeout) { continuation.resume(returning: $0) }
        }
    }

    /// One start's progress, confined to the queue its callbacks run on.
    private final class StartProgress: @unchecked Sendable {
        var settled = false
        var ready = false
    }

    /// A value handed across a semaphore.
    private final class Box<T>: @unchecked Sendable {
        var value: T
        init(_ value: T) { self.value = value }
    }

#if LATCHKEY_TEST_HOOKS
    /// Test hook (R30): kills the app-owned listener and every session the
    /// way iOS does after a suspension. The port WebKit was given stops
    /// answering; tsnet's own listener is untouched, so the status poll sees
    /// nothing and only a failed page load can notice. Lets the L2 harness
    /// exercise the page-driven restart end to end.
    func debugDefunctListener() {
        queue.sync {
            listener?.cancel()
            listener = nil
            for id in Array(sessions.keys) {
                close(id: id, reason: "test hook: listener defuncted")
            }
        }
    }
#endif

    // MARK: - Relay

    private func handle(client: NWConnection) {
        let now = Date()
        // The cap (R30). Refusals and evictions are logged sparingly, as
        // accepts are: a storm of them must not become its own log storm
        // (LogRing aborts the process at 1000 lines/s).
        let active = sessions.map { SocksRelayCapacity.Session(id: $0.key, lastActivity: $0.value.lastActivity) }
        switch capacity.admit(active, now: now) {
        case .accept:
            break
        case .acceptEvicting(let victim, let idle):
            evictions &+= 1
            if evictions <= 3 || evictions.isMultiple(of: 100) {
                logger.log("sockslog: at capacity (\(sessions.count)); evicting socks[\(victim)], silent for \(Int(idle))s (evicted \(evictions) so far)")
            }
            close(id: victim, reason: "evicted at capacity after \(Int(idle))s idle")
        case .refuse:
            refusals &+= 1
            if refusals <= 3 || refusals.isMultiple(of: 100) {
                logger.log("sockslog: at capacity (\(sessions.count)), every session live; refusing a connection (refused \(refusals) so far)")
            }
            client.cancel()
            return
        }

        let id = Self.takeID()
        activeClients[id] = client
        lastAcceptedAt = now
        lifecycleEvents &+= 1
        if lifecycleEvents <= 20 || lifecycleEvents.isMultiple(of: 100) {
            logger.log("socks[\(id)] relay accepted; active=\(activeClients.count), lifecycle=\(lifecycleEvents)")
        }
        client.start(queue: queue)
        beginRelay(client: client, id: id, acceptedAt: now)
    }

    private func beginRelay(client: NWConnection, id: UInt64, acceptedAt: Date) {
        client.stateUpdateHandler = nil
        let upstream = NWConnection(
            host: NWEndpoint.Host(upstreamHost),
            port: NWEndpoint.Port(rawValue: upstreamPort) ?? .any,
            using: .tcp)
        let session = Session(id: id, lastActivity: acceptedAt)
        sessions[id] = session
        activeUpstreams[id] = upstream
        upstream.start(queue: queue)

        // client -> upstream (parse the CONNECT request out of a copy)
        pump(from: client, to: upstream, id: id) { [weak self] data in
            session.lastActivity = Date()
            self?.inspectClientBytes(data, session: session)
        }
        // upstream -> client (parse the reply code out of a copy)
        pump(from: upstream, to: client, id: id) { [weak self] data in
            session.lastActivity = Date()
            self?.inspectServerBytes(data, session: session)
        }
    }

    /// Ends a session from outside its pumps: eviction, or the test hook.
    /// The pumps then finish on their cancelled connections, which the
    /// idempotent `finishRelay` ignores.
    private func close(id: UInt64, reason: String) {
        activeClients[id]?.cancel()
        activeUpstreams[id]?.cancel()
        finishRelay(id: id, reason: reason)
    }

    /// Copies bytes one direction, handing each chunk to `observe` first.
    ///
    /// The callbacks hold the relay STRONGLY, so a relay that was stopped or
    /// replaced still carries its sessions to their end (M6 review). A
    /// loopback recovery drops the manager's reference while the page's
    /// keep-alive connections are still open; with a weak capture each one
    /// relayed one more chunk and then stopped re-arming, neither relaying nor
    /// closing, and the next request WebKit put on it hung with no timeout.
    /// The session's own end (either side closing, an error, an eviction)
    /// releases the relay: nothing re-arms after `finishRelay`.
    private func pump(from: NWConnection,
                      to: NWConnection,
                      id: UInt64,
                      observe: @escaping @Sendable (Data) -> Void) {
        from.receive(minimumIncompleteLength: 1, maximumLength: 64 * 1024) {
            [self] data, _, isComplete, error in
            if let data, !data.isEmpty {
                observe(data)
                to.send(content: data, completion: .contentProcessed { [self] sendError in
                    guard sendError == nil else {
                        logger.log("socks[\(id)] relay send ended: \(String(describing: sendError))")
                        from.cancel()
                        to.cancel()
                        finishRelay(id: id, reason: "send error")
                        return
                    }
                    pump(from: from, to: to, id: id, observe: observe)
                })
                return
            }
            if isComplete || error != nil {
                if let error {
                    logger.log("socks[\(id)] relay receive ended: \(error)")
                }
                from.cancel()
                to.cancel()
                finishRelay(id: id, reason: error == nil ? "complete" : "receive error")
                return
            }

            // `minimumIncompleteLength` is one, so an empty callback with no
            // completion or error cannot make progress. Retrying immediately
            // can become a hot callback loop if iOS has defuncted a connection
            // while the process was suspended. Terminate the relay instead;
            // WebKit can open a fresh SOCKS connection.
            logger.log("socks[\(id)] relay receive made no progress; cancelling")
            from.cancel()
            to.cancel()
            finishRelay(id: id, reason: "no progress")
        }
    }

    private func finishRelay(id: UInt64, reason: String) {
        // Both directional pumps can finish. Removal makes this idempotent and
        // prevents duplicate terminal logs from becoming their own log storm.
        let existed = activeClients.removeValue(forKey: id) != nil
            || activeUpstreams.removeValue(forKey: id) != nil
        activeUpstreams.removeValue(forKey: id)
        sessions.removeValue(forKey: id)
        guard existed else { return }
        lifecycleEvents &+= 1
        logger.log("socks[\(id)] relay finished (\(reason)); active=\(activeClients.count), lifecycle=\(lifecycleEvents)")
    }

    // MARK: - Parsing (read-only; the stream itself is untouched)

    /// Per-connection parse state. Only the handshake is parsed; once the
    /// CONNECT reply is seen the relay stops looking at payload bytes.
    /// Confined to the relay's serial queue; marked Sendable so the Network
    /// framework callback types can express that confinement to Swift 6.
    private final class Session: @unchecked Sendable {
        let id: UInt64
        var clientPhase: ClientPhase = .greeting
        var serverPhase: ServerPhase = .methodSelect
        var pendingClient = Data()
        var pendingServer = Data()
        var target = "?"
        var requestedAt = Date()
        /// The last byte in either direction, or the accept; what the cap
        /// evicts by (R30).
        var lastActivity: Date

        init(id: UInt64, lastActivity: Date) {
            self.id = id
            self.lastActivity = lastActivity
        }

        enum ClientPhase { case greeting, auth, request, done }
        enum ServerPhase { case methodSelect, authReply, connectReply, done }
    }

    private func inspectClientBytes(_ data: Data, session s: Session) {
        guard s.clientPhase != .done else { return }
        s.pendingClient.append(data)

        // Walk as far through the handshake as the buffered bytes allow.
        while true {
            switch s.clientPhase {
            case .greeting:
                // VER | NMETHODS | METHODS...
                guard s.pendingClient.count >= 2 else { return }
                let n = Int(s.pendingClient[s.pendingClient.startIndex + 1])
                let need = 2 + n
                guard s.pendingClient.count >= need else { return }
                let methods = Array(s.pendingClient.dropFirst(2).prefix(n))
                s.pendingClient.removeFirst(need)
                // 0x02 = username/password. tsnet requires it.
                s.clientPhase = methods.contains(0x02) ? .auth : .request
            case .auth:
                // VER | ULEN | UNAME | PLEN | PASSWD
                guard s.pendingClient.count >= 2 else { return }
                let ulen = Int(s.pendingClient[s.pendingClient.startIndex + 1])
                guard s.pendingClient.count >= 2 + ulen + 1 else { return }
                let plen = Int(s.pendingClient[s.pendingClient.startIndex + 2 + ulen])
                let need = 2 + ulen + 1 + plen
                guard s.pendingClient.count >= need else { return }
                s.pendingClient.removeFirst(need)
                s.clientPhase = .request
            case .request:
                // VER | CMD | RSV | ATYP | ADDR | PORT
                guard s.pendingClient.count >= 4 else { return }
                let base = s.pendingClient.startIndex
                let cmd = s.pendingClient[base + 1]
                let atyp = s.pendingClient[base + 3]
                var host = "?"
                var consumed = 4
                switch atyp {
                case 0x01: // IPv4
                    guard s.pendingClient.count >= consumed + 4 else { return }
                    let b = Array(s.pendingClient.dropFirst(consumed).prefix(4))
                    host = b.map(String.init).joined(separator: ".")
                    consumed += 4
                case 0x03: // domain name
                    guard s.pendingClient.count >= consumed + 1 else { return }
                    let len = Int(s.pendingClient[base + consumed])
                    consumed += 1
                    guard s.pendingClient.count >= consumed + len else { return }
                    host = String(decoding: Array(s.pendingClient.dropFirst(consumed).prefix(len)))
                    consumed += len
                case 0x04: // IPv6
                    guard s.pendingClient.count >= consumed + 16 else { return }
                    let b = Array(s.pendingClient.dropFirst(consumed).prefix(16))
                    host = Self.formatIPv6(b)
                    consumed += 16
                default:
                    s.clientPhase = .done
                    return
                }
                guard s.pendingClient.count >= consumed + 2 else { return }
                let pb = Array(s.pendingClient.dropFirst(consumed).prefix(2))
                let port = (UInt16(pb[0]) << 8) | UInt16(pb[1])
                s.pendingClient.removeAll(keepingCapacity: false)
                s.target = "\(host):\(port)"
                s.requestedAt = Date()
                s.clientPhase = .done
                let kind = Self.addrKind(atyp)
                let cmdName = cmd == 0x01 ? "CONNECT" : "cmd=\(cmd)"
                logger.log("socks[\(s.id)] \(cmdName) \(kind) \(s.target) — request reached the tailnet proxy")
                return
            case .done:
                return
            }
        }
    }

    private func inspectServerBytes(_ data: Data, session s: Session) {
        guard s.serverPhase != .done else { return }
        s.pendingServer.append(data)

        while true {
            switch s.serverPhase {
            case .methodSelect:
                guard s.pendingServer.count >= 2 else { return }
                let method = s.pendingServer[s.pendingServer.startIndex + 1]
                s.pendingServer.removeFirst(2)
                s.serverPhase = (method == 0x02) ? .authReply : .connectReply
            case .authReply:
                guard s.pendingServer.count >= 2 else { return }
                let status = s.pendingServer[s.pendingServer.startIndex + 1]
                s.pendingServer.removeFirst(2)
                if status != 0 {
                    logger.log("socks[\(s.id)] proxy auth FAILED (status \(status))")
                    s.serverPhase = .done
                    return
                }
                s.serverPhase = .connectReply
            case .connectReply:
                // VER | REP | RSV | ATYP | BND.ADDR | BND.PORT
                guard s.pendingServer.count >= 2 else { return }
                let rep = s.pendingServer[s.pendingServer.startIndex + 1]
                let ms = Int(Date().timeIntervalSince(s.requestedAt) * 1000)
                if rep == 0 {
                    logger.log("socks[\(s.id)] OK \(s.target) — tailnet proxy connected (\(ms)ms)")
                } else {
                    logger.log("socks[\(s.id)] FAILED \(s.target) — tailnet proxy could not connect: \(Self.replyName(rep)) (reply \(rep), \(ms)ms). WebKit will report this as \"invalid URL\" (-1000).")
                    // The reply name is what the error page needs and what
                    // WebKit destroys (F4 §4.5). `s.target` is the host:port
                    // WebKit asked for, verbatim, which is how the page matches
                    // this reply to its own load.
                    onProxyReply?(ProxyReply(target: s.target, reply: Self.replyName(rep),
                                             elapsed: .milliseconds(ms), at: Date()))
                }
                s.pendingServer.removeAll(keepingCapacity: false)
                s.serverPhase = .done
                return
            case .done:
                return
            }
        }
    }

    // MARK: - Formatting

    private static func addrKind(_ atyp: UInt8) -> String {
        switch atyp {
        case 0x01: return "ipv4"
        case 0x03: return "name"
        case 0x04: return "ipv6"
        default:   return "atyp=\(atyp)"
        }
    }

    /// RFC 1928 reply codes. These are what tsnet's dial failure turns into,
    /// and every one of them is reported by WebKit as -1000.
    private static func replyName(_ rep: UInt8) -> String {
        switch rep {
        case 1: return "general failure"
        case 2: return "connection not allowed"
        case 3: return "network unreachable"
        case 4: return "host unreachable"
        case 5: return "connection refused"
        case 6: return "TTL expired"
        case 7: return "command not supported"
        case 8: return "address type not supported"
        default: return "unknown"
        }
    }

    private static func formatIPv6(_ b: [UInt8]) -> String {
        guard b.count == 16 else { return "?" }
        var parts: [String] = []
        for i in stride(from: 0, to: 16, by: 2) {
            parts.append(String(format: "%x", (Int(b[i]) << 8) | Int(b[i + 1])))
        }
        return parts.joined(separator: ":")
    }
}

private extension String {
    /// Lossy UTF-8 decode of raw SOCKS address bytes (a malformed name must not
    /// crash the relay).
    nonisolated init(decoding bytes: [UInt8]) {
        self = String(bytes: bytes, encoding: .utf8) ?? "?"
    }
}

    TestHooks.flag("-UITestDefunctLoopback") || TestHooks.flag("-UITestShutdownTCPConnections")
        || TestHooks.flag("-UITestDefunctRelayListener")
}

nonisolated private func startTailscale() async {
    do {
        // This sets up a localAPI client attached to the local node.
        let node = try await MainActor.run { try setupNode() }

        // Create a localAPIClient instance for our local node
        let localAPIClient = LocalAPIClient(localNode: node, logger: logger)
        await MainActor.run { setLocalAPIClient(localAPIClient) }

        try await tailscaleUp(localAPI: localAPIClient, consumer: consumer)
        // After the whole start, not at node creation: clearing there would
        // reset the schedule on every retry of a failing tailscaleUp, and
        // the bounded backoff would become a 1 s loop (F8 §3).
        await MainActor.run { nodeStartSucceeded() }

    } catch {
        // Not a trap (F8): a crash here was a crash loop at launch whose
        // only exit, deleting the app, deleted the node's identity.
        await MainActor.run { nodeStartFailed(error) }
    }
}

func tailscaleUp(localAPI: LocalAPIClient, consumer: TSNetConsumer) async throws {
    setProcessor(try await startEventBus(localAPI: localAPI, consumer: consumer))

    // Deliberately do NOT call `node?.up()`. `up()` calls Go's
    // `Up(context.Background())` (non-cancellable), which blocks until the
    // node reaches `Running`. For a no-auth-key node sitting at
    // `NeedsLogin` (every real user before they log in), that blocks the
    // `TailscaleNode` actor's serial executor INDEFINITELY — and since
    // `loopback()`, `close()`, `addrs()` are all on the same actor, EVERY
    // localAPI call (`backendStatus()` polling, `startLoginInteractive()`,
    // a reset's `/logout`, R32) queues behind it and hangs
    // for the whole login window. It also deadlocks `close()` on
    // background (close queues behind up() forever) → two tsnet servers
    // on the same state dir after a bg/fg cycle.
    //
    // `tailscale_start` (called in `TailscaleNode.init`) already sets
    // `WantRunning` + calls `StartLoginInteractive`, so the IPN bus emits
    // `NeedsLogin` + `BrowseToURL` (and later `Running` when the user
    // completes login) on its own — `Up`'s only extra work is a redundant
    // wait-for-`Running`. The bus watcher attached above is the source of
    // truth for state; `startStatusPolling` is the fallback. (Confirmed by
    // the timing harness in timing/: Start→Running ≈ Up→Running, with no
    // actor freeze — see timing/README.md.)
    //
    // The loopback SOCKS5 proxy is up as soon as the node is started, so
    // `proxyConfiguration` can be published now. The initial connection
    // gate does not create the browser until the bus reports `Running`.
    if let loopback = try await self.node?.loopback() {
        await MainActor.run {
            model.proxyConfiguration = proxyConfig(loopback)
        }
    }
}

@MainActor var busErrorWatcher: AnyCancellable?

/// Watches `prefs` so flipping the Exit Node toggle re-scopes the proxy
/// immediately (exit node on => proxy everything so public traffic can
/// egress; off => tailnet only). Without this the change would only take
/// effect on the next 5s status poll.
@MainActor private var prefsWatcher: AnyCancellable?

/// Owns the ordinary IPN-bus error retry. It must be explicitly cancelled:
/// cancelling the Combine sink does not cancel a Task it already spawned.
@MainActor private var busRestartTask: Task<Void, Never>?
/// Backoff belongs to the watcher lifecycle, not to one restart Task. A
/// LocalAPI listener can accept a request and then fail it asynchronously;
/// treating creation of that request as "restart succeeded" otherwise
/// resets backoff on every -1004 and creates a hot retry loop.
@MainActor private var busRestartBackoff: Duration = .milliseconds(500)
@MainActor private var loopbackRecoveryTask: Task<Void, Never>?
@MainActor private var loopbackRecoveryGeneration: UInt64 = 0

/// Starts observing `prefs` for exit-node changes. Idempotent.
@MainActor
private func startPrefsObservation() {
    guard prefsWatcher == nil else { return }
    prefsWatcher = model.$prefs
        .receive(on: DispatchQueue.main)
        .sink { [weak self] _ in
            self?.refreshProxyPolicyIfNeeded()
        }
}

func startEventBus(localAPI: LocalAPIClient,
                   consumer: TSNetConsumer) async throws -> MessageProcessor {
    // This sets up a bus watcher to listen for changes in the netmap.  These will be sent to the given consumer, in
    // this case, a TSNetModel which will keep track of the changes and publish them.
    let busEventMask: Ipn.NotifyWatchOpt = [.initialState]
    let processor = try await localAPI.watchIPNBus(mask: busEventMask,
                                                   consumer: consumer)

    // Any error on the bus consumer indicates the watcher died and needs to
    // be restarted. The watch-ipn-bus long-poll has no keep-alive, so
    // URLSession's default 60s request timeout kills it every minute of
    // idleness — this restart is what keeps state flowing.
    //
    // The restart MUST be robust: the previous version did
    // `let processor = try await startEventBus(...)` inside an unawaited
    // Task with no catch. If that threw (e.g. loopback not ready after a
    // bg/fg cycle), the error was silently swallowed, `consumer.error` had
    // already been cleared, and NO new watcher existed — the app then had
    // NO bus observation forever, so state never updated again (the
    // "click Login/Logout and nothing happens for minutes/ever" hang).
    // Now we catch, log, back off, and retry until the bus comes back or
    // the node is torn down (background).
    let busObserver = await consumer.$error
        .sink { [weak self] error in
            guard let self, let error else { return }
            self.scheduleBusRestart(localAPI: localAPI, consumer: consumer,
                                    error: error)
        }

    // Cancel any prior observer before installing the new one, so the old
    // watcher's sink can't fire again and cascade into concurrent restarts.
    await MainActor.run {
        busErrorWatcher?.cancel()
        busErrorWatcher = busObserver
    }
    return processor
}

@MainActor
private func scheduleBusRestart(localAPI: LocalAPIClient, consumer: TSNetConsumer,
                                error: Error) {
    if Self.isLocalLoopbackConnectionFailure(error) {
        recoverLoopbackAfterFailure(error)
        return
    }
    let delay = busRestartBackoff
    busRestartBackoff = min(busRestartBackoff * 2, .seconds(30))
    logger.log("Bus watcher error: \(error); retrying after \(delay)")
    busRestartTask?.cancel()
    consumer.error = nil
    busRestartTask = Task { [weak self] in
        guard let self else { return }
        do {
            try await Task.sleep(for: delay)
            guard !Task.isCancelled else { return }
            let processor = try await self.startEventBus(
                localAPI: localAPI, consumer: consumer)
            guard !Task.isCancelled else {
                processor.cancel()
                return
            }
            self.setProcessor(processor)
            self.busRestartTask = nil
        } catch is CancellationError {
            return
        } catch {
            // A synchronous setup failure has no consumer callback to drive
            // the next attempt, so feed it through the same persistent
            // backoff path. Async URLSession failures arrive via consumer.
            self.busRestartTask = nil
            self.scheduleBusRestart(localAPI: localAPI, consumer: consumer,
                                    error: error)
        }
    }
}

nonisolated private static func isLocalLoopbackConnectionFailure(_ error: Error) -> Bool {
    let ns = error as NSError
    guard ns.domain == NSURLErrorDomain,
          (ns.code == NSURLErrorCannotConnectToHost
            || ns.code == NSURLErrorNetworkConnectionLost)
    else { return false }
    let rawURL = (ns.userInfo[NSURLErrorFailingURLErrorKey] as? URL)?.absoluteString ?? ""
    guard let host = URL(string: rawURL)?.host()?.lowercased() else { return false }
    return host == "127.0.0.1" || host == "localhost" || host == "::1"
}

@MainActor
private func recoverLoopbackAfterFailure(_ cause: Error) {
    guard loopbackRecoveryTask == nil, let node else { return }
    loopbackRecoveryGeneration &+= 1
    let generation = loopbackRecoveryGeneration
    logger.log("LocalAPI loopback failure: \(cause); replacing loopback generation \(generation)")
    busRestartTask?.cancel()
    busRestartTask = nil
    loopbackRecoveryTask = Task { [weak self] in
        guard let self else { return }
        do {
            let loopback = try await node.restartLoopback()
            guard !Task.isCancelled,
                  generation == self.loopbackRecoveryGeneration else { return }

            // Every LocalAPI request asks the node actor for its cached
            // config, now replaced above. Restart the stream immediately.
            let newConsumer = TSNetConsumer(logger: logger, model: self.model)
            let newClient = LocalAPIClient(localNode: node, logger: logger)
            let newProcessor = try await self.startEventBus(
                localAPI: newClient, consumer: newConsumer)
            guard !Task.isCancelled,
                  generation == self.loopbackRecoveryGeneration else {
                newProcessor.cancel()
                return
            }
            self.consumer = newConsumer
            self.localAPIClient = newClient
            self.setProcessor(newProcessor)

            // Replace the app-owned relay too: its upstream port and SOCKS
            // credential changed with the tsnet loopback listener. The
            // old relay's sessions ride tsnet's accepted connections,
            // which a closed listener leaves open, so they run on to
            // their end (`SocksLogProxy.stop`); only new ones use this.
            self.socksLogProxy?.stop()
            self.socksLogProxy = nil
            self.socksLogProxyPort = nil
            self.model.proxyConfiguration = self.proxyConfig(loopback)
            self.busRestartBackoff = .milliseconds(500)
            self.loopbackRecoveryTask = nil
            self.model.tcpChaosTestStatus = "recovered"
            logger.log("LocalAPI loopback recovered at \(loopback.address), generation \(generation)")
        } catch {
            guard !Task.isCancelled,
                  generation == self.loopbackRecoveryGeneration else { return }
            self.loopbackRecoveryTask = nil
            logger.log("LocalAPI loopback replacement failed: \(error); retrying through bus backoff")
            self.scheduleBusRestart(localAPI: localAPIClient ?? LocalAPIClient(localNode: node, logger: logger),
                                    consumer: self.consumer, error: error)
        }
    }
}

func setLocalAPIClient(_ client: TailscaleKit.LocalAPIClient) {
    self.localAPIClient = client
    startPrefsObservation()
    startStatusPolling()
}

/// Polls `backendStatus()` every few seconds and publishes it on the model,
/// so per-tab connection-type indicators stay current.
@MainActor
func startStatusPolling() {
    guard statusPollTask == nil else { return }
    statusPollTask = Task { [weak self] in
        while !Task.isCancelled {
            guard let self else { return }
            if let client = await MainActor.run(body: { self.localAPIClient }) {
                do {
                    let status = try await client.backendStatus()
                    await MainActor.run {
                        // A successful request proves the local listener is
                        // carrying bytes again; future watcher failures may
                        // start from the short retry delay.
                        self.busRestartBackoff = .milliseconds(500)
                        self.model.localStatus = status
                        if status.BackendState == "Running" {
                            self.runTCPChaosTestIfNeeded()
                        }
                        // Fallback state signal: model.state is normally
                        // driven by the IPN bus, but if the bus watcher is
                        // mid-restart (or has died — see startEventBus),
                        // state would go stale indefinitely. Mirror the
                        // polled BackendState into model.state so the UI's
                        // gate/LoginBanner/Login-button react within one
                        // poll interval (5s) instead of waiting for the bus.
                        if let s = Self.ipnState(fromBackendState: status.BackendState),
                           self.model.state != s {
                            self.model.state = s
                        }
                        // Fold newly-discovered peers / the MagicDNS suffix
                        // into the proxy's split-tunnel rules. The proxy is
                        // published before the first poll, so without this
                        // the rule set would stay IP-ranges-only and bare
                        // MagicDNS names (`http://ai/`) would load DIRECT
                        // and fail. No-op when the rules are unchanged.
                        self.refreshProxyPolicyIfNeeded()
                    }
                } catch {
                    await MainActor.run {
                        logger.log("Status poll failed: \(error)")
                        if Self.isLocalLoopbackConnectionFailure(error) {
                            self.recoverLoopbackAfterFailure(error)
                        }
                    }
                }
            }
            try? await Task.sleep(nanoseconds: 5_000_000_000) // 5s
        }
    }
}

func setProcessor(_ processor: MessageProcessor) {
    self.processor?.cancel()
    self.processor = processor
}

func setupNode() throws -> TailscaleNode {
    guard self.node == nil else { return self.node! }
    self.node = try TailscaleNode(config: config, logger: logger)
    return self.node!
}

/// Builds the SOCKS5 `ProxyConfiguration` for WebKit, scoped by
/// `TailnetProxyPolicy` so ONLY tailnet destinations are proxied and the
/// public internet loads DIRECT.
///
/// The scoping is what fixes the iPad `-1000` ("invalid URL") bug. Measured
/// fact: `-1000` is what WebKit/CFNetwork report for ANY SOCKS5 CONNECT
/// failure, so it means "the proxy could not connect" — not "bad URL".
/// Public hosts therefore must not depend on the tsnet proxy at all. See
/// the file comment in `TailnetProxyPolicy.swift` for the candidate
/// mechanisms and the verified `matchDomains` semantics.
///
/// `-ProxyEverything` restores the old proxy-everything behaviour, so the
/// two modes can be A/B'd on a real device with no rebuild (the iPad in
/// the bug report can't be attached to a Mac).
func proxyConfig(_ loopbackConfig: TailscaleNode.LoopbackConfig) -> ProxyConfiguration? {
    guard let ip = loopbackConfig.ip, let port = loopbackConfig.port else {
        return nil
    }
    return proxyConfig(upstreamHost: ip, upstreamPort: port,
                       credential: loopbackConfig.proxyCredential)
}

/// The same, from plain values: tsnet's loopback listener in production,
/// or the stub proxy in the offline test harness (R11). Starts the
/// logging relay in front of it when enabled, records the endpoint for
/// later rescoping, and builds the configuration through
/// `ProxyConfigurationFactory`.
func proxyConfig(upstreamHost ip: String, upstreamPort port: Int,
                 credential: String) -> ProxyConfiguration? {

    // Route WebKit through the logging relay (Settings → Logs) so every
    // connection attempt that reaches the tailnet proxy is recorded with
    // its outcome. tsnet's own SOCKS server logs only failures and not the
    // reply code, so without this the absence of a log line is ambiguous:
    // it could mean "iOS never sent it to us" OR "it succeeded".
    var proxyHost = ip
    var proxyPort = port
    if SocksLogProxy.isEnabled() {
        if socksLogProxy == nil,
           let upstreamPort = UInt16(exactly: port) {
            let relay = SocksLogProxy(upstreamHost: ip, upstreamPort: upstreamPort,
                                      onListenerFailed: { [weak self] failed in
                Task { @MainActor [weak self] in self?.relayListenerFailed(failed) }
            }, onProxyReply: { [weak self] reply in
                // One hop to the main actor, where the page reads it (F4
                // §4.5). Last-one-wins is correct: a sweep's twelve refusals
                // are all for hosts the page is not loading, and the page
                // matches on target and time before believing any of them.
                Task { @MainActor [weak self] in self?.model.lastProxyFailure = reply }
            })
            if let localPort = relay.start() {
                socksLogProxy = relay
                socksLogProxyPort = localPort
            } else {
                recordRelayFallback(after: "no listener could be started")
            }
        }
        if let localPort = socksLogProxyPort {
            proxyHost = "127.0.0.1"
            proxyPort = Int(localPort)
        }
    }

    recordProxyEndpoint(host: proxyHost, port: proxyPort, credential: credential)
    let policy = StableProxyPolicy.make(from: model.localStatus,
                                         exitNodeEnabled: proxyEverythingRequested())
    guard let proxyConfig = ProxyConfigurationFactory.make(
        proxyHost: proxyHost, proxyPort: proxyPort,
        credential: credential, policy: policy)
    else {
        logger.log("proxyConfig: invalid proxy endpoint port \(proxyPort); not publishing")
        return nil
    }
    model.proxyPolicy = policy
    if policy.proxiesEverything {
        logger.log("proxyConfig: proxying ALL hosts (-ProxyEverything test hook). Public traffic only works if something carries it out of the tailnet.")
    } else {
        logger.log("proxyConfig: split tunnel, proxying \(policy.matchDomains.count) rule(s): \(policy.matchDomains.joined(separator: ", "))")
    }
    if !policy.shortNamesWithheldAsPublicTLD.isEmpty {
        logger.log("proxyConfig: short names withheld (public-TLD collision), reachable via FQDN: \(policy.shortNamesWithheldAsPublicTLD.joined(separator: ", "))")
    }
    return proxyConfig
}

/// Re-derives the proxy's `matchDomains` from the latest peer status and
/// republishes it if the rule set changed.
///
/// The proxy is published as soon as the node starts — before the first
/// `/status` poll — so the initial rule set is only the tailnet IP ranges.
/// Once peers are known (and whenever they change: a peer joins, or
/// MagicDNS arrives) the short names and MagicDNS suffix must be folded in,
/// or bare names like `http://ai/` would load DIRECT and fail.
@MainActor
func refreshProxyPolicyIfNeeded() {
    guard model.proxyConfiguration != nil else { return }
    let policy = StableProxyPolicy.make(from: model.localStatus,
                                         exitNodeEnabled: proxyEverythingRequested())
    guard policy != model.proxyPolicy else { return }
    // Build a fresh configuration rather than editing the published one:
    // ProxyConfiguration's copies share storage, so upstream's
    // `var updated = model.proxyConfiguration; updated.matchDomains = …`
    // rewrote the object already installed in WebKit's data store (R12).
    guard let endpoint = proxyEndpoint,
          let updated = ProxyConfigurationFactory.make(
            proxyHost: endpoint.host, proxyPort: endpoint.port,
            credential: endpoint.credential, policy: policy)
    else { return }
    model.proxyPolicy = policy
    model.proxyConfiguration = updated
    logger.log("proxyConfig: policy updated — \(policy.matchDomains.joined(separator: ", "))")
    if !policy.shortNamesWithheldAsPublicTLD.isEmpty {
        logger.log("proxyConfig: short names withheld (public-TLD collision), reachable via FQDN: \(policy.shortNamesWithheldAsPublicTLD.joined(separator: ", "))")
    }
}

/// The page reports a load that failed (R30). If it looks like WebKit could
/// not reach the logging relay -- a transport error while the node is
/// Running and tsnet's own loopback answers, with the relay having
/// accepted nothing for the navigation -- the relay's own port is probed,
/// and a listener that refuses the probe is restarted and the proxy
/// configuration republished, which the page takes as its cue to retry.
/// The verdict is `SocksRelayRecovery`'s; this gathers its evidence.
/// Failures the relay accepted (a dead gateway is also -1000) are left
/// alone: the relay's own log line says what tsnet replied, and a new
/// listener would change nothing. So is a listener that answers the
/// probe (R30 review): the accept inference misreads a pooled connection
/// WebKit reused, and a failure that never dialed the proxy.
@MainActor
func pageLoadFailed(_ failure: SocksRelayRecovery.PageFailure) {
    guard let relay = socksLogProxy, let port = socksLogProxyPort,
          SocksRelayRecovery.isTransportFailure(domain: failure.domain, code: failure.code)
    else { return }
    // Read before the loopback round trip: a connection accepted for
    // something else meanwhile (the probe's own, for one) must not pass
    // for this load's.
    let accepted = relay.hasAcceptedSession(since: failure.navigationStartedAt)
    Task { [weak self] in
        guard let self else { return }
        let answers = await self.refreshStatusNow()
        var evidence = SocksRelayRecovery.Evidence(
            failure: failure,
            // A loopback recovery may have replaced the relay meanwhile.
            relayInUse: self.socksLogProxy === relay && self.socksLogProxyPort == port,
            nodeRunning: self.model.state == .Running,
            loopbackRecoveryInFlight: self.loopbackRecoveryTask != nil,
            upstreamAnswers: answers,
            relayAcceptedSinceNavigation: accepted)
        if case .probe = SocksRelayRecovery.decide(evidence) {
            // The final guard, and the one that costs a connection: only
            // once everything else points at the listener.
            let outcome = await SocksLogProxy.probe(port: port)
            self.countProbe(outcome)
            evidence = evidence.probed(outcome)
        }
        switch SocksRelayRecovery.decide(evidence) {
        case .restart:
            self.restartSocksRelayWithinBudget(
                reason: "page failed with \(failure.domain) \(failure.code), nothing reached the relay, and its listener \(evidence.listener?.rawValue ?? "?") a probe")
        case .leave(let reason):
            logger.log("sockslog: relay listener kept after \(failure.domain) \(failure.code): \(reason)")
        case .probe:
            // Unreachable: the probe's finding is in the evidence now.
            break
        }
    }
}

/// The dashboard session check got no answer twice in a row (R30
/// review). The page-world fetch says nothing about why -- the gateway,
/// the tailnet, or the relay's port under it -- so the relay's listener
/// is probed, and restarted only if it refuses.
@MainActor
func sessionCheckUnanswered() {
    probeRelayListener(trigger: "session check unanswered twice")
}

