@discardableResult
public func editPrefs(mask: Ipn.MaskedPrefs) async throws -> Ipn.Prefs {
    let result = await doJSONAPIRequest(
        endpoint: .prefs,
        method: .PATCH,
        bodyAsJSON: mask,
        resultTransformer: jsonDecodeTransformer(Ipn.Prefs.self))

    switch result {
